SELECT CASE WHEN amount >= 1320 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, CASE WHEN discount >= 0.36 THEN 'HIGH' ELSE 'LOW' END AS discount_tier, ROUND(AVG(amount), 2) AS avg_amount, ROUND(AVG(discount), 2) AS avg_discount, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, PERCENTILE_APPROX(shipping_fee, 0.95) AS shipping_fee_p95, ROUND(AVG(discount), 2) AS avg_discount_2, PERCENTILE_APPROX(discount, 0.9) AS discount_p90, RANK() OVER (PARTITION BY CASE WHEN amount >= 1320 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY PERCENTILE_APPROX(shipping_fee, 0.95) DESC) AS shipping_fee_p95_rank FROM orders GROUP BY 1, 2 HAVING PERCENTILE_APPROX(shipping_fee, 0.95) < 0 ORDER BY avg_discount NULLS LAST
